parameters.functionCode:
// Load knowledge base context
// In production: load from vector DB
// In POC: inline JSON
const knowledgeBase = [
  {
    topic: 'home_water_damage',
    q: 'Does home insurance cover water damage from a burst pipe?',
    a: 'Yes. Burst pipe water damage is covered under Hausratversicherung as Leitungswasser damage. Covers furniture, electronics, personal belongings. EUR 250 deductible applies. Flooding from outside requires separate flood cover.'
  },
  {
    topic: 'claim_process',
    q: 'How do I file a claim?',
    a: 'File online at mypolicy.example.com, by calling this line, or email claims@example-insurance.de. You need: policy number, incident date, description, photos if available. Acknowledged within 2 business days.'
  },
  {
    topic: 'claim_timeline',
    q: 'How long does claim processing take?',
    a: 'Standard claims: 10-15 business days. Complex claims (>EUR 5,000): up to 30 days. Email updates provided. Urgent claims (emergency repairs) can be fast-tracked.'
  },
  {
    topic: 'policy_renewal',
    q: 'How do I renew my policy?',
    a: 'Policies renew automatically. Renewal notice sent 6 weeks before renewal date. To cancel: written notice 4 weeks before renewal date. To update coverage: call or use online portal.'
  },
  {
    topic: 'premium_increase',
    q: 'Why has my premium increased?',
    a: 'Premiums change due to: annual market adjustment, changes to risk profile, or a prior claim. Breakdown in renewal letter. Errors can be escalated to billing specialist.'
  },
  {
    topic: 'cancel_policy',
    q: 'How do I cancel my policy?',
    a: 'Cancel at annual renewal with 4 weeks written notice. Immediate cancellation possible if risk circumstances change significantly. Send signed letter/email to cancellations@example-insurance.de with policy number.'
  }
];

const kbContext = knowledgeBase
  .map(item => `Q: ${item.q}\nA: ${item.a}`)
  .join('\n\n');

return [{ json: { ...items[0].json, kbContext } }];

const { message, conversation_id, history, kbContext, turn_number } = items[0].json;

const historyText = history && history.length > 0
  ? '\n\nConversation so far:\n' + history.map(t => `${t.role}: ${t.text}`).join('\n')
  : '';

const isFirstTurn = !turn_number || turn_number === 1;
const disclosureInstruction = isFirstTurn
  ? 'IMPORTANT: This is the first turn. You MUST begin your response by identifying yourself as an AI: "Hi, I am InsurBot, an AI assistant for Allianz Direct." This is required by EU AI Act Article 52.'  
  : 'Do NOT repeat the AI disclosure — you already gave it on the first turn.';

const systemPrompt = `You are InsurBot, an AI-powered customer service agent for Allianz Direct insurance.

${disclosureInstruction}

Your role:
- Answer insurance queries accurately using ONLY the knowledge base provided
- If the answer is not in the knowledge base, say so honestly and offer to escalate
- Never make up policy terms, coverage details, or claim decisions
- Be concise, warm, and professional
- Detect escalation signals: explicit request for human, expressions of anger/distress, legal threats, complaints

KNOWLEDGE BASE:
${kbContext}

Respond ONLY with a JSON object in this exact format (no markdown):
{
  "intent": "<one of: policy_coverage | file_claim | claim_status | billing_query | policy_renewal | cancel_policy | escalate_human | general_info | out_of_scope>",
  "confidence": <0.0-1.0>,
  "response": "<your response to the customer>",
  "should_escalate": <true|false>,
  "escalation_reason": "<null or brief reason>"
}`;

return [{ json: { ...items[0].json, systemPrompt, historyText } }];

const raw = items[0].json.content[0].text.trim();
let parsed;
try {
  parsed = JSON.parse(raw);
} catch(e) {
  // Fallback if Claude wraps in markdown
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : {
    intent: 'general_info',
    confidence: 0.5,
    response: 'I apologise, I had trouble understanding. Could you rephrase your question?',
    should_escalate: false,
    escalation_reason: null
  };
}

return [{ json: { ...items[0].json, ...parsed } }];

